"""What each Company Laws category video says and shows. One entry per category; one dict per scene.
kinds: title | rules | app (a real screenshot of the app) | sanction | quiz.  Photos come from docs/adverts/photos.
Edit the wording here and run render.py again."""

SANCTION_SAY = ("Every law has penalty points. For now, breaking a law costs one point, and your points are always shown at the top of your profile. "
                "At twenty points, the sanction is a three day suspension, with ten hours deducted. At thirty points, a one week suspension, with twenty hours deducted. "
                "At fifty points, dismissal. The owner approves every sanction. Keep a clean record for a week and five points come off. "
                "For the first two weeks, violations are only warnings while everyone learns.")
SANCTION_BULLETS = ["1 point for each violation, for now", "20 points: 3-day suspension, 10 hours deducted", "30 points: 1-week suspension, 20 hours deducted",
                    "50 points: dismissal", "A clean week: 5 points come off", "Your points show at the top of your profile"]

def sanction(example):
    return dict(kind="sanction", heading="If a law is broken", bullets=SANCTION_BULLETS + [example], say=SANCTION_SAY + " For example: " + example + ".")

def quiz(say="Now take the quiz for this category on the Company Laws screen. It has a few short questions and takes one minute."):
    return dict(kind="quiz", heading="Take the quiz", bullets=["Open Company Laws", "Choose this category", "Answer the questions", "Anything you miss is explained"], say=say)

